// Stable tracer identities: NIST. Transport coefficients: illustrative, shared by all elements.
export const elements={C:{name:'Carbon',isotopes:[13,12],carrier:'Carbon in a labelled organic substrate; individual metabolites and carbon positions are not resolved.'},N:{name:'Nitrogen',isotopes:[15,14],carrier:'Nitrogen in a labelled nitrogen-containing substrate; amino-acid reactions are not resolved.'},S:{name:'Sulfur',isotopes:[34,33,36,32],carrier:'Sulfur in a labelled sulfur-containing substrate; sulfur chemistry is not resolved.'},Cu:{name:'Copper',isotopes:[65,63]},Zn:{name:'Zinc',isotopes:[68,67,66,70,64]},Ca:{name:'Calcium',isotopes:[44,43,42,46,40]},Fe:{name:'Iron',isotopes:[57,58,56,54]},Mg:{name:'Magnesium',isotopes:[25,26,24]},Se:{name:'Selenium',isotopes:[77,78,76,74,80]}};
export function newTracer(symbol){return {symbol,isotope:elements[symbol].isotopes[0],pools:[0,0,0,0],removed:0,injected:0,time:0,transport:1,retention:1,history:[],events:[]};}
export function pulse(t){t.pools[0]+=100;t.injected+=100;t.events.push({time:t.time,action:'pulse_100_units'});record(t);}
export function chase(t){t.removed+=t.pools[0];t.pools[0]=0;t.events.push({time:t.time,action:'wash_to_tracer_free_bath'});record(t);}
export function record(t){t.history.push({time:t.time,pools:[...t.pools],removed:t.removed,injected:t.injected,transport:t.transport,retention:t.retention});}
export function stepTracer(t,dt){
 // Exact two-pool exchange substeps preserve positivity and atom count.
 const exchange=(a,b,kab,kba)=>{const sum=t.pools[a]+t.pools[b],k=kab+kba;if(!k)return;const eq=sum*kba/k;const next=eq+(t.pools[a]-eq)*Math.exp(-k*dt);t.pools[a]=next;t.pools[b]=sum-next;};
 exchange(0,1,.025*t.transport,.012*t.transport);
 exchange(1,2,.018*t.retention,.003);
 exchange(1,3,.008*t.transport,.004*t.transport);
 t.time+=dt;if(!t.history.length||t.time-t.history.at(-1).time>=.5)record(t);
}
export function mountTracerLab(root){
 let runs=Object.fromEntries(Object.keys(elements).map(s=>[s,newTracer(s)])),selected='C';
 root.innerHTML=`<div class="membrane-header"><div><span class="section-number">NEW</span><h2>Follow the atoms</h2><span class="membrane-subtitle">Stable-isotope pulse–chase laboratory</span></div><span class="version">ILLUSTRATIVE TRANSPORT</span></div><div class="tracer-elements" role="group" aria-label="Tracer element">${Object.keys(elements).map(s=>`<button type="button" data-element="${s}" aria-pressed="false">${s}</button>`).join('')}</div><div class="membrane-grid"><div class="membrane-card"><h3 id="tracer-name"></h3><p id="tracer-carrier" class="membrane-note"></p><label class="tracer-field">Isotope <select id="tracer-isotope"></select></label><label class="tracer-field">Transport speed <select id="tracer-transport"><option value="0">Blocked</option><option value="0.25">0.25×</option><option value="1" selected>1×</option><option value="4">4×</option></select></label><label class="tracer-field">Retention rate <select id="tracer-retention"><option value="0">No capture</option><option value="1" selected>1×</option><option value="4">4×</option></select></label><div class="tracer-actions"><button id="tracer-pulse">Add labelled pulse</button><button id="tracer-chase">Wash / chase</button><button id="tracer-reset">Reset element</button></div><p class="membrane-note">Each pulse adds 100 normalized units of the selected isotope. This is tagged material above an unmodelled background, not natural isotope abundance or a physiological dose. Changing isotope clears this element’s run.</p></div><div class="membrane-card"><h3>Where is the label?</h3><div id="tracer-pools"></div><p id="tracer-balance" role="status" class="membrane-note"></p><p class="membrane-note">Bath ↔ mobile cytosolic pool ↔ retained pool / organelle pool. These are generic transport compartments, not atom-resolved reactions. The organelle pool is not assigned to a specific organelle.</p></div><div class="membrane-card"><h3>Label inside the cell</h3><svg id="tracer-chart" viewBox="0 0 360 150" role="img" aria-label="Intracellular label over time"></svg><p id="tracer-chart-caption" class="membrane-note"></p><button id="tracer-export">Export all tracer runs</button><p class="membrane-note">Uses the cell’s play, pause and speed controls. Cell reset or preset change clears all tracer runs. Switching element preserves its run.</p></div></div><details class="tracer-details"><summary>Model, evidence &amp; limitations</summary><p>All nine elements currently share the same user-adjustable transport law: bath → cytosol 0.025×transport s⁻¹; return 0.012×transport s⁻¹; cytosol → retained 0.018×retention s⁻¹; release 0.003 s⁻¹; cytosol → organelle 0.008×transport s⁻¹; return 0.004×transport s⁻¹. Exact pairwise exchange substeps conserve label and keep pools nonnegative. Rates are illustrative, not measured element-specific kinetics.</p><p>Chase removes bath label into an accounted discarded pool. No further label is added unless you pulse again. Isotope selection changes identity only: no kinetic isotope effect, radiation, toxicity, speciation, protein-specific binding, calcium signalling or feedback on ATP, voltage or mechanics is simulated. C, N and S labels represent atoms carried in molecules, not free elemental atoms; metabolic atom mapping is a future module.</p><p>Isotope identities checked against <a href="https://pml.nist.gov/cgi-bin/Compositions/stand_alone.pl?ascii=ascii" target="_blank" rel="noopener noreferrer">NIST atomic weights and isotopic compositions</a>. This catalogue is a selected stable-isotope set, not every naturally occurring isotope. Results are schematic hypotheses for exploration, not calibrated mammalian-cell predictions.</p></details>`;
 const $=id=>root.querySelector('#'+id),names=['Bath','Cytosol · mobile','Retained / bound proxy','Organelle · generic'];
 function select(){const t=runs[selected],e=elements[selected];$('tracer-name').textContent=e.name+' · '+selected;$('tracer-carrier').textContent=e.carrier||'Label follows a generic element-containing mobile pool. Oxidation state, ligands and specific transporters are not resolved.';$('tracer-isotope').innerHTML=e.isotopes.map(n=>`<option value="${n}">${n}${selected}</option>`).join('');$('tracer-isotope').value=t.isotope;$('tracer-transport').value=t.transport;$('tracer-retention').value=t.retention;root.querySelectorAll('[data-element]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.element===selected)));render();}
 function render(){const t=runs[selected],scale=Math.max(t.injected,100);$('tracer-pools').innerHTML=t.pools.map((v,i)=>`<div class="tracer-pool"><span>${names[i]}</span><strong>${v.toFixed(2)}</strong><progress value="${v}" max="${scale}" aria-label="${names[i]} labelled units"></progress></div>`).join('');const sum=t.pools.reduce((a,b)=>a+b,0)+t.removed;$('tracer-balance').textContent=`${t.isotope}${selected} · ${t.time.toFixed(1)} s · Added ${t.injected.toFixed(0)} · Discarded ${t.removed.toFixed(2)} · Balance error ${(sum-t.injected).toExponential(1)} units`;
 const h=t.history.filter(d=>d.time>=t.time-120),start=Math.max(0,t.time-120),width=Math.max(120,t.time-start);const points=h.map(d=>`${(28+310*(d.time-start)/width).toFixed(2)},${(120-100*(d.pools[1]+d.pools[2]+d.pools[3])/scale).toFixed(2)}`).join(' ');$('tracer-chart').innerHTML=`<path d="M28 15V120H345" fill="none" stroke="#a5b1aa"/><text x="28" y="12">${scale} units</text><text x="10" y="124">0</text><polyline points="${points}" fill="none" stroke="#4d7863" stroke-width="3"/>`;$('tracer-chart-caption').textContent=`Window ${start.toFixed(0)}–${(start+width).toFixed(0)} s · cytosol + retained + organelle. ${t.injected?'':'Add a pulse to begin.'}`;
 }
 root.querySelectorAll('[data-element]').forEach(b=>b.onclick=()=>{selected=b.dataset.element;select();});
 $('tracer-isotope').onchange=()=>{const isotope=Number($('tracer-isotope').value);runs[selected]=newTracer(selected);runs[selected].isotope=isotope;select();};
 for(const key of ['transport','retention'])$('tracer-'+key).onchange=()=>{const t=runs[selected];t[key]=Number($('tracer-'+key).value);t.events.push({time:t.time,action:key+'_'+t[key]});record(t);render();};
 $('tracer-pulse').onclick=()=>{pulse(runs[selected]);render();};$('tracer-chase').onclick=()=>{chase(runs[selected]);render();};$('tracer-reset').onclick=()=>{runs[selected]=newTracer(selected);select();};
 $('tracer-export').onclick=()=>{const rows=['element,isotope,time_s,bath_units,cytosol_units,retained_units,organelle_units,discarded_units,injected_units,transport_multiplier,retention_multiplier,event'];for(const t of Object.values(runs)){for(const d of t.history)rows.push([t.symbol,t.isotope,d.time,...d.pools,d.removed,d.injected,d.transport,d.retention,''].join(','));for(const e of t.events)rows.push([t.symbol,t.isotope,e.time,'','','','','','','','',e.action].join(','));}const url=URL.createObjectURL(new Blob([rows.join('\r\n')],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download='cellula-isotope-tracers.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 select();return {step(dt){Object.values(runs).forEach(t=>{if(t.injected)stepTracer(t,dt);});},render,reset(){runs=Object.fromEntries(Object.keys(elements).map(s=>[s,newTracer(s)]));select();}};
}
